"use client";

/**
 * /news — Daily Brief page.
 *
 * Desktop: 5-column layout — one column per category
 *   Football · Geopolitics · Business · Tech · AI
 *
 * Mobile: category tabs + vertical story list
 *
 * Stories are generated by Claude with live web search (web_search_20250305 tool).
 * Results are cached per-user per-day in the DB.
 */

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Newspaper, RefreshCw, ExternalLink } from "lucide-react";
import type { NewsBrief, NewsCategory, NewsStory } from "@/lib/news-brief";

// ─── Category config ──────────────────────────────────────────────────────────

type CatConfig = { label: string; icon: string; color: string };

const CATEGORIES: NewsCategory[] = ["football", "geopolitics", "business", "tech", "ai"];

const CAT: Record<NewsCategory, CatConfig> = {
  football:    { label: "Football",    icon: "⚽", color: "#F97316" },
  geopolitics: { label: "Geopolitics", icon: "🌍", color: "#F87171" },
  business:    { label: "Business",    icon: "📈", color: "#34D399" },
  tech:        { label: "Tech",        icon: "💻", color: "#22D3EE" },
  ai:          { label: "AI",          icon: "🤖", color: "#A78BFA" },
};

// ─── Story card ───────────────────────────────────────────────────────────────

function StoryCard({ story }: { story: NewsStory }) {
  const [expanded, setExpanded] = useState(false);
  const cfg = CAT[story.category as NewsCategory] ?? { label: "News", icon: "📰", color: "var(--text-muted)" };

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      className="rounded-xl p-4 cursor-pointer transition-colors"
      style={{
        background: "var(--bg-card)",
        border: "1px solid var(--border-subtle)",
        borderLeft: `3px solid ${cfg.color}`,
      }}
      onClick={() => setExpanded((v) => !v)}
    >
      <h3
        className="text-sm font-semibold leading-snug"
        style={{ color: "var(--text-primary)" }}
      >
        {story.headline}
      </h3>

      <AnimatePresence>
        {expanded && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            style={{ overflow: "hidden" }}
          >
            <p className="text-xs leading-relaxed mt-2" style={{ color: "var(--text-secondary)" }}>
              {story.summary}
            </p>
            <div
              className="mt-2 rounded-lg p-2.5"
              style={{ background: "var(--bg-elevated)" }}
            >
              <p className="text-[11px]" style={{ color: "var(--text-muted)" }}>
                <span className="font-semibold" style={{ color: cfg.color }}>Why it matters · </span>
                {story.whyItMatters}
              </p>
            </div>
            {story.source && (
              <a
                href={story.source}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-1 mt-2 text-[10px] hover:underline"
                style={{ color: "var(--text-muted)" }}
                onClick={(e) => e.stopPropagation()}
              >
                <ExternalLink size={10} />
                Source
              </a>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

// ─── Column skeleton ──────────────────────────────────────────────────────────

function ColumnSkeleton() {
  return (
    <div className="space-y-2">
      {[80, 64, 96, 72, 56].map((h, i) => (
        <div
          key={i}
          className="rounded-xl animate-pulse"
          style={{ height: h, background: "var(--bg-card)" }}
        />
      ))}
    </div>
  );
}

// ─── Category column ──────────────────────────────────────────────────────────

function CategoryColumn({
  category,
  stories,
  loading,
}: {
  category: NewsCategory;
  stories: NewsStory[];
  loading: boolean;
}) {
  const cfg = CAT[category];

  return (
    <div className="min-w-0">
      {/* Column header */}
      <div className="flex items-center gap-2 mb-3 pb-2" style={{ borderBottom: `1px solid ${cfg.color}33` }}>
        <span className="text-base">{cfg.icon}</span>
        <span className="text-sm font-semibold" style={{ color: cfg.color }}>
          {cfg.label}
        </span>
        {!loading && (
          <span className="text-xs ml-auto" style={{ color: "var(--text-muted)" }}>
            {stories.length}
          </span>
        )}
      </div>

      {loading ? (
        <ColumnSkeleton />
      ) : stories.length === 0 ? (
        <p className="text-xs text-center py-6" style={{ color: "var(--text-muted)" }}>
          No stories found
        </p>
      ) : (
        <div className="space-y-2">
          {stories.map((s, i) => (
            <StoryCard key={i} story={s} />
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Main page ─────────────────────────────────────────────────────────────────

export default function NewsPage() {
  const [brief, setBrief]         = useState<NewsBrief | null>(null);
  const [loading, setLoading]     = useState(true);
  const [generating, setGenerating] = useState(false);
  const [mobileTab, setMobileTab] = useState<NewsCategory>("football");

  const load = async () => {
    const res = await fetch("/api/news/generate").catch(() => null);
    if (res?.ok) {
      const data = await res.json();
      setBrief(data);
    }
    setLoading(false);
  };

  const generate = async () => {
    setGenerating(true);
    const res = await fetch("/api/news/generate", { method: "POST" }).catch(() => null);
    if (res?.ok) {
      const data = await res.json();
      setBrief(data);
    }
    setGenerating(false);
  };

  useEffect(() => { load(); }, []);

  const today = new Date().toLocaleDateString("en-GB", {
    weekday: "long", day: "numeric", month: "long", year: "numeric",
  });

  // Group stories by category
  const byCategory = (cat: NewsCategory): NewsStory[] =>
    (brief?.stories ?? []).filter((s) => s.category === cat);

  return (
    <div className="page-enter p-5 md:p-8">
      {/* Header */}
      <div className="flex items-start justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold tracking-tight" style={{ color: "var(--text-primary)" }}>
            Daily Brief
          </h1>
          <p className="text-sm mt-0.5" style={{ color: "var(--text-muted)" }}>
            {today}
            {brief && !loading && (
              <> · {brief.stories.length} stories · live web search</>
            )}
          </p>
        </div>
        <button
          onClick={generate}
          disabled={generating || loading}
          className="flex items-center gap-2 px-3 py-2 rounded-xl text-sm transition-all disabled:opacity-50"
          style={{
            background: "var(--bg-elevated)",
            color: "var(--text-secondary)",
            border: "1px solid var(--border-subtle)",
          }}
        >
          <RefreshCw size={14} className={generating ? "animate-spin" : ""} />
          {generating ? "Searching…" : "Refresh"}
        </button>
      </div>

      {/* No brief + not loading */}
      {!loading && !generating && !brief && (
        <div
          className="rounded-2xl p-12 flex flex-col items-center gap-4 text-center"
          style={{ background: "var(--bg-card)", border: "1px solid var(--border-subtle)" }}
        >
          <Newspaper size={36} style={{ color: "var(--text-muted)" }} />
          <p style={{ color: "var(--text-secondary)" }}>No brief generated yet for today.</p>
          <button
            onClick={generate}
            className="px-5 py-2.5 rounded-xl text-sm font-semibold"
            style={{ background: "var(--accent-primary)", color: "#fff" }}
          >
            Generate Today's Brief
          </button>
          <p className="text-xs" style={{ color: "var(--text-muted)" }}>
            Takes ~30s — Claude searches the web for real news
          </p>
        </div>
      )}

      {/* Generating spinner */}
      {generating && (
        <div
          className="rounded-2xl p-12 flex flex-col items-center gap-3 text-center"
          style={{ background: "var(--bg-card)", border: "1px solid var(--border-subtle)" }}
        >
          <RefreshCw size={28} className="animate-spin" style={{ color: "var(--accent-primary)" }} />
          <p className="font-medium" style={{ color: "var(--text-primary)" }}>
            Searching the web…
          </p>
          <p className="text-sm" style={{ color: "var(--text-muted)" }}>
            Claude is finding today's top stories across all 5 categories
          </p>
        </div>
      )}

      {/* ── Desktop: 5-column grid ─────────────────────────────── */}
      {(loading || brief) && !generating && (
        <>
          <div
            className="hidden md:grid gap-4"
            style={{ gridTemplateColumns: "repeat(5, minmax(0, 1fr))" }}
          >
            {CATEGORIES.map((cat) => (
              <CategoryColumn
                key={cat}
                category={cat}
                stories={byCategory(cat)}
                loading={loading}
              />
            ))}
          </div>

          {/* ── Mobile: tab bar + list ───────────────────────────── */}
          <div className="md:hidden space-y-4">
            {/* Category tab strip */}
            <div
              className="flex overflow-x-auto gap-1 pb-1 -mx-1 px-1"
              style={{ scrollbarWidth: "none" }}
            >
              {CATEGORIES.map((cat) => {
                const cfg = CAT[cat];
                const active = mobileTab === cat;
                return (
                  <button
                    key={cat}
                    onClick={() => setMobileTab(cat)}
                    className="shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium transition-all"
                    style={{
                      background: active ? `${cfg.color}22` : "var(--bg-elevated)",
                      color: active ? cfg.color : "var(--text-muted)",
                      border: active ? `1px solid ${cfg.color}44` : "1px solid transparent",
                    }}
                  >
                    {cfg.icon} {cfg.label}
                    {!loading && (
                      <span className="opacity-60">{byCategory(cat).length}</span>
                    )}
                  </button>
                );
              })}
            </div>

            {/* Active category stories */}
            <AnimatePresence mode="wait">
              <motion.div
                key={mobileTab}
                initial={{ opacity: 0, x: 12 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -12 }}
                transition={{ duration: 0.15 }}
              >
                {loading ? (
                  <ColumnSkeleton />
                ) : (
                  <div className="space-y-2">
                    {byCategory(mobileTab).length === 0 ? (
                      <p className="text-sm text-center py-10" style={{ color: "var(--text-muted)" }}>
                        No stories found
                      </p>
                    ) : (
                      byCategory(mobileTab).map((s, i) => (
                        <StoryCard key={i} story={s} />
                      ))
                    )}
                  </div>
                )}
              </motion.div>
            </AnimatePresence>
          </div>

          {/* Footer */}
          {brief && !loading && (
            <p className="text-xs text-center mt-6" style={{ color: "var(--text-muted)" }}>
              Generated {new Date(brief.generatedAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })} · Live web search · Claude
            </p>
          )}
        </>
      )}
    </div>
  );
}
